{
  "findings": [
    {
      "check_id": "CKV_GCP_29",
      "title": "Uniform bucket-level access is not enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not enable uniform bucket-level access, allowing legacy object ACLs to create an additional and potentially inconsistent access-control path."
    },
    {
      "check_id": "CKV_GCP_114",
      "title": "Public access prevention is not enforced",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "HIGH",
      "explanation": "Public access prevention is not explicitly enforced, so the bucket could become publicly accessible through current or future IAM or ACL configuration."
    }
  ],
  "patched_code": "resource \"google_storage_bucket\" \"compliance_storage\" {\n  name                        = \"${var.project_id}-digital-asset-trading-platform-compliance\"\n  location                    = var.region\n  uniform_bucket_level_access = true\n  public_access_prevention    = \"enforced\"\n\n  versioning {\n    enabled = true\n  }\n\n  lifecycle_rule {\n    condition {\n      age = 2555\n    }\n    action {\n      type = \"Delete\"\n    }\n  }\n}\n",
  "fix_summary": "Enabled uniform bucket-level access to eliminate legacy object ACLs and enforced public access prevention on the bucket. Existing versioning and lifecycle configuration were retained."
}
